using System;
using UnityEngine;

namespace Wrestling.Presentation
{
    /// <summary>
    /// The wrestler character assets built from MakeHuman (tools/characters/build_wrestlers.py):
    /// one base model per gender with its skins and part materials. Generated by the editor's
    /// character library builder from the exported files; not edited by hand.
    /// </summary>
    public sealed class CharacterLibrary : ScriptableObject
    {
        [Serializable]
        public sealed class SkinSet
        {
            public string Name;
            public Texture2D Albedo;
            public Texture2D Normal;
        }

        [Serializable]
        public sealed class CharacterBase
        {
            public string Name;
            public GameObject Model;

            /// <summary>Template for the body (Wrestling/Wrestler Skin); each wrestler gets an instance with their skin and singlet colour.</summary>
            public Material Body;

            /// <summary>Materials for the other parts (eyes, brows, lashes, hair, shoes), by renderer name.</summary>
            public string[] PartNames = Array.Empty<string>();
            public Material[] PartMaterials = Array.Empty<Material>();
            public SkinSet[] Skins = Array.Empty<SkinSet>();
        }

        public CharacterBase Male;
        public CharacterBase Female;

        public CharacterBase For(bool female) => female ? Female : Male;
    }
}
